import { prisma } from '../src/lib/db';
import path from 'path';
import fs from 'fs';
const { generateTintedImage } = require('./tint-images.js');

async function main() {
  console.log('🌱 Starting to seed tinted variants...');

  // Use the images generated by the assistant
  const baseSwatchPath = '/home/moayad/.gemini/antigravity-ide/brain/d722240d-7cbd-4fe7-9386-288ce62a62f1/base_swatch_1789470421811.jpg';
  const baseModelPath = '/home/moayad/.gemini/antigravity-ide/brain/d722240d-7cbd-4fe7-9386-288ce62a62f1/base_model_1789470440778.jpg';

  if (!fs.existsSync(baseSwatchPath) || !fs.existsSync(baseModelPath)) {
    console.error('❌ Base images not found! Check paths.');
    return;
  }

  // Find all variants that have a colorHex defined
  const variants = await prisma.productVariant.findMany({
    where: {
      colorHex: { not: null }
    }
  });

  console.log(`Found ${variants.length} variants with colors.`);

  for (const variant of variants) {
    if (!variant.colorHex) continue;
    
    console.log(`Processing variant: ${variant.name} (${variant.colorHex})`);
    
    // Clean filename friendly string
    const safeName = variant.name.replace(/[^a-z0-9]/gi, '_').toLowerCase();
    
    const swatchFileName = `swatch-${variant.id}-${safeName}.png`;
    const modelFileName = `model-${variant.id}-${safeName}.png`;

    // Generate images using the tint-images utility
    await generateTintedImage(baseSwatchPath, variant.colorHex, swatchFileName);
    await generateTintedImage(baseModelPath, variant.colorHex, modelFileName);

    // Update the variant in the database with the new local paths
    await prisma.productVariant.update({
      where: { id: variant.id },
      data: {
        swatchImage: `/images/variants/${swatchFileName}`,
        modelImage: `/images/variants/${modelFileName}`
      }
    });
  }

  console.log('✅ Successfully seeded all tinted images!');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
